use sieve::{sieve, is_prime};

#[test]
fn test_sieve_small() {
    assert_eq!(sieve(10), vec![2, 3, 5, 7]);
}

#[test]
fn test_sieve_zero_one() {
    assert_eq!(sieve(0), vec![]);
    assert_eq!(sieve(1), vec![]);
    assert_eq!(sieve(2), vec![2]);
}

#[test]
fn test_sieve_20() {
    assert_eq!(sieve(20), vec![2, 3, 5, 7, 11, 13, 17, 19]);
}

#[test]
fn test_is_prime() {
    assert!(!is_prime(0));
    assert!(!is_prime(1));
    assert!(is_prime(2));
    assert!(is_prime(13));
    assert!(!is_prime(15));
}

#[test]
fn test_is_prime_large() {
    assert!(is_prime(97));
    assert!(!is_prime(100));
}
